begin;
with j as (select * from jsonb_to_recordset($law7d0002$[{"code_id":"APK_RF","article_number":"123","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса считаются извещенными надлежащим образом, если к началу судебного заседания, совершения отдельного процессуального действия арбитражный суд располагает сведениями о получении адресатом копии определения о принятии искового заявления или заявления к производству и возбуждении производства по делу, направленной ему в порядке, установленном настоящим Кодексом, или иными доказательствами получения лицами, участвующими в деле, информации о начавшемся судебном процессе.\n\n2. Гражданин считается извещенным надлежащим образом, если судебное извещение вручено ему лично или совершеннолетнему лицу, проживающему совместно с этим гражданином, под расписку на подлежащем возврату в арбитражный суд уведомлении о вручении либо ином документе с указанием даты и времени вручения, а также источника информации.\n\n3. Судебное извещение, адресованное юридическому лицу, вручается лицу, уполномоченному на получение корреспонденции.\n\n4. Лица, участвующие в деле, и иные участники арбитражного процесса также считаются извещенными надлежащим образом арбитражным судом, если:\n\n1) адресат отказался от получения копии судебного акта и этот отказ зафиксирован организацией почтовой связи или арбитражным судом;\n\n2) несмотря на почтовое извещение, адресат не явился за получением копии судебного акта, направленной арбитражным судом в установленном порядке, о чем организация почтовой связи уведомила арбитражный суд;\n\n3) копия судебного акта не вручена в связи с отсутствием адресата по указанному адресу, о чем организация почтовой связи уведомила арбитражный суд с указанием источника данной информации;\n\n4) судебное извещение вручено уполномоченному лицу филиала или представительства юридического лица;\n\n5) судебное извещение вручено представителю лица, участвующего в деле;\n\n6) имеются доказательства вручения или направления судебного извещения в порядке, установленном частями 2 и 3 статьи 122 настоящего Кодекса;\n\n7) имеется подтверждение доставки судебного извещения посредством единого портала государственных и муниципальных услуг участнику арбитражного процесса, давшему согласие на едином портале государственных и муниципальных услуг на уведомление его посредством единого портала государственных и муниципальных услуг, или доставки судебного извещения посредством системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение пунктом - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 123. Надлежащее извещение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ea53f7f23a9ecafd5baa1da9f76ff1517fc16d4fa001a8979c163e4e64291a7"},{"code_id":"APK_RF","article_number":"124","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, обязаны сообщить арбитражному суду об изменении своего наименования. При отсутствии такого сообщения лицо, участвующее в деле, именуется в судебном акте исходя из последнего известного арбитражному суду наименования этого лица.\n\n2. Лица, участвующие в деле, обязаны сообщить арбитражному суду об изменении своего адреса во время производства по делу. При отсутствии такого сообщения копии судебных актов направляются по последнему известному арбитражному суду адресу и считаются доставленными, хотя бы адресат по этому адресу более не находится или не проживает.\n\n3. В случае, если лицо, участвующее в деле, сообщало арбитражному суду номера телефонов и факсов, адрес электронной почты или аналогичную информацию, оно должно проинформировать арбитражный суд об их изменении во время производства по делу.\n\n4. Арбитражный суд указывает в определении или протоколе судебного заседания изменение наименования лица, участвующего в деле, его адреса, номеров телефонов и факсов, адреса электронной почты или аналогичной информации.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)\n\nРАЗДЕЛ II. ПРОИЗВОДСТВО В АРБИТРАЖНОМ СУДЕ ПЕРВОЙ ИНСТАНЦИИ. ИСКОВОЕ ПРОИЗВОДСТВО","article_title":"Статья 124. Изменение наименования лица, перемена адреса во время производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0eb59e04278baa1c3d742aef7160acd4b3ba72c2580007916bc8695310d2cc1f"},{"code_id":"APK_RF","article_number":"125","version_date":"2002-07-24","article_text":"1. Исковое заявление подается в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Исковое заявление подписывается истцом или его представителем.\n\nИсковое заявление, подаваемое в электронном виде, содержащее ходатайство об обеспечении иска, должно быть подписано усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В исковом заявлении должны быть указаны:\n\n1) наименование арбитражного суда, в который подается исковое заявление;\n\n2) сведения об истце: для гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы или дата и место государственной регистрации в качестве индивидуального предпринимателя и один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, серия и номер водительского удостоверения), номера телефонов, факсов, адреса электронной почты; для организации - наименование, адрес, идентификационный номер налогоплательщика, номера телефонов, факсов, адреса электронной почты; (В редакции Федерального закона от 21.12.2021 № 417-ФЗ)\n\n3) сведения об ответчике: для гражданина - фамилия, имя, отчество (при наличии), дата и место рождения, место жительства или место пребывания, место работы (если известно) и один из идентификаторов (страховой номер индивидуального лицевого счета, идентификационный номер налогоплательщика, серия и номер документа, удостоверяющего личность, основной государственный регистрационный номер индивидуального предпринимателя, серия и номер водительского удостоверения); для организации - наименование, адрес, идентификационный номер налогоплательщика и основной государственный регистрационный номер. В случае, если гражданину неизвестны дата и место рождения ответчика, один из его идентификаторов, об этом указывается в исковом заявлении и такая информация по запросу арбитражного суда предоставляется органами Фонда пенсионного и социального страхования Российской Федерации, и (или) налоговыми органами, и (или) органами внутренних дел. В этом случае срок принятия искового заявления к производству арбитражного суда, предусмотренный частью 1 статьи 127 настоящего Кодекса, исчисляется со дня получения арбитражным судом такой информации; (В редакции  федеральных законов от 21.12.2021 № 417-ФЗ, от 28.12.2022 № 569-ФЗ)\n\n4) требования истца к ответчику со ссылкой на законы и иные нормативные правовые акты, а при предъявлении иска к нескольким ответчикам - требования к каждому из них;\n\n5) обстоятельства, на которых основаны исковые требования, и подтверждающие эти обстоятельства доказательства;\n\n6) цена иска, если иск подлежит оценке;\n\n7) расчет взыскиваемой или оспариваемой денежной суммы;\n\n8) сведения о соблюдении истцом претензионного или иного досудебного порядка; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n81) сведения о предпринятых стороной (сторонами) действиях, направленных на примирение, если такие действия предпринимались; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n9) сведения о мерах, принятых арбитражным судом по обеспечению имущественных интересов до предъявления иска;\n\n10) перечень прилагаемых документов.\n\nВ заявлении должны быть указаны и иные сведения, если они необходимы для правильного и своевременного рассмотрения дела, могут содержаться ходатайства, в том числе ходатайства об истребовании доказательств от ответчика или других лиц. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 125. Форма и содержание искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"66da65bf5d0f0c06198671cc0f8eefc05f27b456743d70b621c75cd2954f1bfe"},{"code_id":"APK_RF","article_number":"126","version_date":"2002-07-24","article_text":"1) уведомление о вручении или иные документы, подтверждающие направление другим лицам, участвующим в деле, копий искового заявления и приложенных к нему документов, которые у других лиц, участвующих в деле, отсутствуют, в том числе в случае подачи в суд искового заявления и приложенных к нему документов в электронном виде; (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2) документ, подтверждающий уплату государственной пошлины в установленных порядке и в размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки, об уменьшении размера государственной пошлины;\n\n3) документы, подтверждающие обстоятельства, на которых истец основывает свои требования;\n\n4) (Пункт утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n5) доверенность или иные документы, подтверждающие полномочия на подписание искового заявления, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего исковое заявление, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n6) копии определения арбитражного суда об обеспечении имущественных интересов до предъявления иска;\n\n7) документы, подтверждающие соблюдение истцом претензионного или иного досудебного порядка, за исключением случаев, если его соблюдение не предусмотрено федеральным законом; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n71) документы, подтверждающие совершение стороной (сторонами) действий, направленных на примирение, если такие действия предпринимались и соответствующие документы имеются; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n8) проект договора, если заявлено требование о понуждении заключить договор;\n\n9) выписка из единого государственного реестра юридических лиц или единого государственного реестра индивидуальных предпринимателей с указанием сведений о месте нахождения или месте жительства истца и ответчика и (или) приобретении физическим лицом статуса индивидуального предпринимателя либо прекращении физическим лицом деятельности в качестве индивидуального предпринимателя или иной документ, подтверждающий указанные сведения или отсутствие таковых. Такие документы должны быть получены не ранее чем за тридцать дней до дня обращения истца в арбитражный суд. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 126. Документы, прилагаемые к исковому заявлению","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c76b24c34a14168b4cc2b73bb2cd051b66829820de8a1c70408609582af3b5"},{"code_id":"APK_RF","article_number":"127","version_date":"2002-07-24","article_text":"1. Вопрос о принятии искового заявления к производству арбитражного суда решается судьей единолично в пятидневный срок со дня поступления искового заявления в арбитражный суд.\n\n2. Арбитражный суд обязан принять к производству исковое заявление, поданное с соблюдением требований, предъявляемых настоящим Кодексом к его форме и содержанию.\n\n3. О принятии искового заявления арбитражный суд выносит определение, которым возбуждается производство по делу.","article_title":"Статья 127. Принятие искового заявления и возбуждение производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"592a07a1646ad3be3c3c7ae6f73d60a942cbcf86ccc551b009c574c7fda4f4f7"},{"code_id":"APK_RF","article_number":"127.1","version_date":"2002-07-24","article_text":"1. Судья отказывает в принятии искового заявления, заявления, если:\n\n1) исковое заявление, заявление подлежат рассмотрению в порядке конституционного или уголовного судопроизводства либо не подлежат рассмотрению в судах; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) имеются вступивший в законную силу принятый по спору между теми же лицами, о том же предмете и по тем же основаниям судебный акт арбитражного суда, суда общей юрисдикции или компетентного суда иностранного государства, за исключением случаев, если арбитражный суд отказал в признании и приведении в исполнение решения иностранного суда, а также определение о прекращении производства по делу в связи с принятием отказа истца от иска или утверждением мирового соглашения сторон либо определение об отказе в принятии искового заявления, заявления;\n\n3) имеется ставшее обязательным для сторон и принятое по спору между теми же сторонами, о том же предмете и по тем же основаниям решение третейского суда, за исключением случаев, если арбитражный суд отказал в выдаче исполнительного листа на принудительное исполнение решения третейского суда либо если арбитражный суд отменил указанное решение.\n\n2. Судья Суда по интеллектуальным правам отказывает в принятии заявления об оспаривании нормативного правового акта либо акта, содержащего разъяснения законодательства и обладающего нормативными свойствами, в случае, если имеется вступившее в законную силу решение арбитражного суда или суда общей юрисдикции по ранее рассмотренному делу, проверившего по тем же основаниям соответствие оспариваемого нормативного правового акта иному нормативному правовому акту, имеющему большую юридическую силу, либо проверившего по тем же основаниям оспариваемый акт, содержащий разъяснения законодательства и обладающий нормативными свойствами.\n\n3. Об отказе в принятии искового заявления, заявления судья выносит определение, в котором указывает обстоятельства, послужившие основанием для отказа в принятии искового заявления, заявления, и решает вопрос о возврате государственной пошлины лицу, предъявившему исковое заявление, заявление, если государственная пошлина была уплачена. Копия определения вместе с исковым заявлением, заявлением и прилагаемыми к нему документами направляется указанному лицу не позднее пяти дней со дня поступления искового заявления, заявления в суд.\n\n4. Отказ в принятии искового заявления, заявления препятствует повторному обращению в суд с такими заявлениями к тому же ответчику, о том же предмете и по тем же основаниям.\n\n5. Определение арбитражного суда об отказе в принятии искового заявления, заявления может быть обжаловано.\n\nВ случае отмены определения об отказе в принятии искового заявления, заявления такие заявления считаются поданными в день первоначального обращения в арбитражный суд.\n\n(Дополнение статьей - Федеральный закон от 19.12.2016 № 435-ФЗ)","article_title":"Статья 127.1. Отказ в принятии искового заявления, заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a51bb11b7bb6bfa393f3443ebf61c1dfc83004be94713ffb678ecfd7ad791a2"},{"code_id":"APK_RF","article_number":"128","version_date":"2002-07-24","article_text":"1. Арбитражный суд, установив при рассмотрении вопроса о принятии искового заявления к производству, что оно подано с нарушением требований, установленных статьями 125 и 126 настоящего Кодекса, выносит определение об оставлении заявления без движения.\n\n2. В определении арбитражный суд указывает основания для оставления искового заявления без движения и срок, в течение которого истец должен устранить обстоятельства, послужившие основанием для\n\nоставления искового заявления без движения.\n\nКопия определения об оставлении искового заявления без движения направляется истцу не позднее следующего дня после дня его вынесения.\n\n3. В случае, если обстоятельства, послужившие основанием для оставления искового заявления без движения, будут устранены в срок, установленный в определении арбитражного суда, заявление считается поданным в день его первоначального поступления в суд и принимается к производству арбитражного суда.\n\n4. В случае, если указанные в части 2 настоящей статьи обстоятельства не будут устранены в срок, установленный в определении, арбитражный суд возвращает исковое заявление и прилагаемые к нему документы в порядке, предусмотренном статьей 129 настоящего Кодекса.","article_title":"Статья 128. Оставление искового заявления без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1bb085de35495a00e3c921dd63eb186fef0cec2f8a22095d494a0f7489927e49"},{"code_id":"APK_RF","article_number":"129","version_date":"2002-07-24","article_text":"1. Арбитражный суд возвращает исковое заявление, если при рассмотрении вопроса о принятии заявления установит, что:\n\n1) дело неподсудно данному арбитражному суду или подсудно суду общей юрисдикции; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) (Пункт утратил силу - Федеральный закон от 19.07.2009 № 205-ФЗ)\n\n21) заявленные требования подлежат рассмотрению в порядке приказного производства; (Дополнение пунктом - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n3) до вынесения определения о принятии искового заявления к производству арбитражного суда от истца поступило ходатайство о возвращении заявления;\n\n4) не устранены обстоятельства, послужившие основаниями для оставления искового заявления без движения, в срок, установленный в определении суда;\n\n5) истцом не соблюден претензионный или иной досудебный порядок урегулирования спора с ответчиком, если такой порядок является обязательным в силу закона; (Дополнение пунктом - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\n6) исковое заявление не подписано или исковое заявление подписано  лицом, не имеющим полномочий на его подписание. (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\nАрбитражный суд также возвращает исковое заявление, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера.\n\n2. О возвращении искового заявления арбитражный суд выносит определение.\n\nВ определении указываются основания для возвращения заявления, решается вопрос о возврате государственной пошлины из федерального бюджета.\n\n3. Копия определения о возвращении искового заявления направляется истцу не позднее следующего дня после дня вынесения определения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления заявления без движения, вместе с заявлением и прилагаемыми к нему документами.\n\n4. Определение арбитражного суда о возвращении искового заявления может быть обжаловано.\n\n5. В случае отмены определения исковое заявление считается поданным в день первоначального обращения в арбитражный суд.\n\n6. Возвращение искового заявления не препятствует повторному обращению с таким же требованием в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для его возвращения.","article_title":"Статья 129. Возвращение искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61b583bab63927a6fcfc88e92869864d4ce27fc3e68e5fbddb46863302bc0510"},{"code_id":"APK_RF","article_number":"13","version_date":"2002-07-24","article_text":"1. Арбитражные суды рассматривают дела на основании Конституции Российской Федерации, международных договоров Российской Федерации, федеральных конституционных законов, федеральных законов, нормативных правовых актов Президента Российской Федерации и нормативных правовых актов Правительства Российской Федерации, нормативных правовых актов федеральных органов исполнительной власти, конституций (уставов), законов и иных нормативных правовых актов субъектов Российской Федерации, актов органов местного самоуправления.\n\nАрбитражные суды в случаях, предусмотренных федеральным законом, применяют обычаи делового оборота.\n\n2. Арбитражный суд, установив при рассмотрении дела несоответствие нормативного правового акта иному имеющему большую юридическую силу нормативному правовому акту, в том числе издание его с превышением полномочий, принимает судебный акт в соответствии с нормативным правовым актом, имеющим большую юридическую силу.\n\n3. Если при рассмотрении конкретного дела арбитражный суд придет к выводу о несоответствии закона, примененного или подлежащего применению в рассматриваемом деле, Конституции Российской Федерации, арбитражный суд обращается в Конституционный Суд Российской Федерации с запросом о проверке конституционности этого закона.","article_title":"Статья 13. Нормативные правовые акты, применяемые при рассмотрении дел","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e1d65e6d88d045156e65ce9a44f9c000cd866afc7117fb1def5632eaffc08e9"},{"code_id":"APK_RF","article_number":"130","version_date":"2002-07-24","article_text":"1. Истец вправе соединить в одном заявлении несколько требований, связанных между собой по основаниям возникновения или представленным доказательствам.\n\n2. Арбитражный суд первой инстанции вправе объединить несколько однородных дел, в которых участвуют одни и те же лица, в одно производство для совместного рассмотрения.","article_title":"Статья 130. Соединение и разъединение нескольких требований","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a48c3df1d1096c20c1e9e91b67f1923e80dc77e6ceff5f365f5cf7526a52b170"},{"code_id":"APK_RF","article_number":"131","version_date":"2002-07-24","article_text":"1. Ответчик обязан направить или представить в арбитражный суд и лицам, участвующим в деле, отзыв на исковое заявление с указанием возражений относительно предъявленных к нему требований по каждому доводу, содержащемуся в исковом заявлении.\n\nТакой отзыв и прилагаемые к нему документы могут быть представлены в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В случаях и в порядке, которые установлены настоящим Кодексом, иные участники арбитражного процесса вправе направить в арбитражный суд и другим лицам, участвующим в деле, отзыв в письменной форме на исковое заявление.\n\nОтветчик направляет отзыв на исковое заявление на бумажном носителе в арбитражный суд и лицам, участвующим в деле, заказным письмом с уведомлением о вручении. Отзыв на исковое заявление в электронном виде направляется лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n1) наименование истца, его адрес или, если истцом является гражданин, его место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) наименование ответчика, его адрес или, если ответчиком является гражданин, его место жительства, дата и место рождения, место работы или дата и место государственной регистрации в качестве индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) возражения относительно каждого довода, касающегося существа заявленных требований, со ссылкой на законы и иные нормативные правовые акты, а также на доказательства, обосновывающие возражения;\n\n31) сведения о предпринятых ответчиком действиях, направленных на примирение, если такие действия предпринимались; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n32) мнение ответчика о возможности примирения сторон; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n4) перечень прилагаемых к отзыву документов, в том числе подтверждающих совершение ответчиком действий, направленных на примирение, если такие действия предпринимались и соответствующие документы имеются. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 131. Отзыв на исковое заявление","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc6602f6b17eec5626b71757116987274c5af2184fc7500e17eedb1131c0b22d"},{"code_id":"APK_RF","article_number":"132","version_date":"2002-07-24","article_text":"1. Ответчик до принятия арбитражным судом первой инстанции судебного акта, которым заканчивается рассмотрение дела по существу, вправе предъявить истцу встречный иск для рассмотрения его совместно с первоначальным иском.\n\n2. Предъявление встречного иска осуществляется по общим правилам предъявления исков.\n\n3. Встречный иск принимается арбитражным судом в случае, если:\n\n1) встречное требование направлено к зачету первоначального требования;\n\n2) удовлетворение встречного иска исключает полностью или в части удовлетворение первоначального иска;\n\n3) между встречным и первоначальным исками имеется взаимная связь и их совместное рассмотрение приведет к более быстрому и правильному рассмотрению дела.\n\n4. Арбитражный суд возвращает встречный иск, если отсутствуют условия, предусмотренные частью 3 настоящей статьи, по правилам статьи 129 настоящего Кодекса.","article_title":"Статья 132. Предъявление встречного иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b56e2820a171cce36fd1e11f428655cfe9b41ef1adde7237d4316c029772809a"},{"code_id":"APK_RF","article_number":"133","version_date":"2002-07-24","article_text":"1. Задачами подготовки дела к судебному разбирательству являются определение характера спорного правоотношения и подлежащего применению законодательства, обстоятельств, имеющих значение для правильного рассмотрения дела; разрешение вопроса о составе лиц, участвующих в деле, и других участников арбитражного процесса; оказание содействия лицам, участвующим в деле, в представлении необходимых доказательств; примирение сторон.\n\n2. Подготовка дела к судебному разбирательству проводится судьей единолично по каждому находящемуся в производстве арбитражного суда первой инстанции делу в целях обеспечения его правильного и своевременного рассмотрения.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 133. Задачи подготовки дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bd525880ef4c1904113e9f25750144c1d7a28abf44943a58e84d1f3667913c0"},{"code_id":"APK_RF","article_number":"134","version_date":"2002-07-24","article_text":"1. Арбитражный суд первой инстанции после принятия заявления к производству выносит определение о подготовке дела к судебному разбирательству и указывает сторонам на возможность заявить ходатайство о рассмотрении дела с участием арбитражных заседателей, обратиться за содействием к суду или посреднику, в том числе медиатору, судебному примирителю, в целях урегулирования спора или использовать другие примирительные процедуры, а также на действия, которые надлежит совершить лицам, участвующим в деле, и сроки совершения этих действий.\n\nВ целях урегулирования спора судья принимает меры для примирения сторон, в том числе может предложить сторонам использовать какую-либо примирительную процедуру, отложить проведение предварительного судебного заседания, совершение других подготовительных действий.\n\nНа подготовку дела к судебному разбирательству может быть указано в определении о принятии заявления к производству.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n2. Подготовка дела к судебному разбирательству проводится в срок, определяемый судьей с учетом обстоятельств конкретного дела и необходимости совершения соответствующих процессуальных действий, и завершается проведением предварительного судебного заседания, если в соответствии с настоящим Кодексом не установлено иное.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 134. Срок подготовки дела к судебному разбирательству","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a65fbfdeb1daa31926001690ec33ea96a5d96efbe83a5ecc5d54a74634bc3aa"}]$law7d0002$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
